<template>
    <div class="ecom-element ecom-shopify-elements ecom-shopify__blog">
        <div class="ecom-shopify__blog-wrapper ecom-swiper-a11y-host">
            <button
                v-if="$helpers.hasAutoplayToggle(data.settings)"
                type="button"
                class="ecom-swiper-autoplay-toggle"
                :data-position="data.settings?.a11y_autoplay_control_position || 'bottom-right'"
                data-state="playing"
                data-label-pause="Pause automatic slide show"
                data-label-play="Start automatic slide show"
                aria-label="Pause automatic slide show"
            >
                <svg class="ecom-swiper-autoplay-toggle__pause" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M8 5h3v14H8zM13 5h3v14h-3z"/></svg>
                <svg class="ecom-swiper-autoplay-toggle__play" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M8 5v14l11-7z"/></svg>
            </button>
            <template v-if="layout === 'slider'">
                <div
                    class="ecom-shopify__blog-container ecom-swiper-container"
                    :data-items-on-row="items_on_row"
                    v-html="liquid('blog')"
                />
                <div
                      v-if="isNavigation && isCombined == 'combine'"
                      class="ecom-swiper-navigation"
                      :data-navigator-type="isCombined == 'combine'"
                  >
                      <div class="ecom-flex-center">
                          <button
                              v-show="isArrow()"
                              class="ecom-swiper-button ecom-swiper-button-prev"
                              v-html="data.settings.slider_prev_icon"
                          />
                          <div v-show="isPagination()" class="ecom-swiper-pagination" />
                          <button
                              v-show="isArrow()"
                              class="ecom-swiper-button ecom-swiper-button-next"
                              v-html="data.settings.slider_next_icon"
                          />
                      </div>
                </div>
                <div v-if="isNavigation && !(isCombined == 'combine')" v-show="isArrow()" class="ecom-swiper-navigation-position" :data-position="data.settings.navigation_position">
                    <button
                        class="ecom-swiper-button ecom-swiper-button-prev"
                        :style="sliderNav"
                        v-html="data.settings.slider_prev_icon"
                    />
                    <button
                        class="ecom-swiper-button ecom-swiper-button-next"
                        :style="sliderNav"
                        v-html="data.settings.slider_next_icon"
                    />
                </div>
                <div v-if="isNavigation && !(isCombined == 'combine')" v-show="isPagination()"
                :data-position="data.settings?.pagination_position"
                :data-position-tablet="data.settings?.pagination_position__tablet"
                :data-position-mobile="data.settings?.pagination_position__mobile"
                class="ecom-swiper-pagination-position ecom-swiper-pagination"
                />
            </template>
            <div
                v-else
                class="ecom-shopify__blog-container"
                :data-items-on-row="items_on_row"
                v-html="liquid('blog')"
            />
            <div class="ecom-collection__product-loading ecom-dn">
            <svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" style="margin: auto; background: none; display: block; shape-rendering: auto;" width="48px" height="48px" viewBox="0 0 100 100" preserveAspectRatio="xMidYMid">
                <path d="M10 50A40 40 0 0 0 90 50A40 42 0 0 1 10 50" fill="#0a0a0a" stroke="none">
                  <animateTransform attributeName="transform" type="rotate" dur="0.5434782608695652s" repeatCount="indefinite" keyTimes="0;1" values="0 50 51;360 50 51"></animateTransform>
                </path>
            </svg>
        </div>
        </div>
    </div>
</template>

<script>
import { Liquid, Element, Javascript } from '@/mixins';
export default {
    name: 'BlogFeatured',
    mixins: [Liquid, Element, Javascript],
    vendors: ['slider_js', 'slider_css'],
    props: {
        data: {
            type: Object,
            default() {
                return {};
            }
        }
    },
    data() {
        return {
            jsreactives: [
                'layout'
            ]
        };
    },
    computed: {
        csrContext() {
            if (!this.canUseCustomLiquidForCSR || this?.data?.template !== "featured") return undefined;
            const blog = this.data.settings?.blog;

            const handles = typeof blog?.value === "string" && blog.value.trim() !== ""
                ? [blog.value]
                : Array.isArray(blog)
                    ? blog.map(b => b.value).filter(Boolean)
                    : null;

            return {
                type: "blogs",
                handles
            }
        },
        articles() {
            return this.data;
        },
        attributes() {
            return this.data.settings && this.data.settings.attributes
                ? this.data.settings.attributes
                : [];
        },
        isNavigation() {
            return (
                this.data.settings?.layout === "slider" && this.data.settings?.slider_navigation_layout
            );
        },
        isCombined() {
          let navigator = this.data?.settings?.slider_navigation_layout;
          return navigator === 'neo_full' ? 'combine' : 'classic';
        },
        sliderNav(){
            if(!this.data.settings.navigation_position__tablet) {
                this.data.settings.navigation_position__tablet = this.data.settings.navigation_position;
            }
            if(!this.data.settings.navigation_position__mobile) {
                this.data.settings.navigation_position__mobile = this.data.settings.navigation_position;
            }

            return {
                '--ecom-position': this.data.settings.navigation_position !== 'center' ? 'unset' : 'absolute',
                '--ecom-position__tablet': this.data.settings.navigation_position__tablet !== 'center' ? 'unset' : 'absolute',
                '--ecom-position__mobile': this.data.settings.navigation_position__mobile !== 'center' ? 'unset' : 'absolute',
            }
        },
        css() {
            return `
${this.$helpers.autoplayToggleCss()}

                    .ecom-shopify__blog--post-informations {
                        display: inline-flex;
                        align-items: center;
                        gap: 5px;
                    }
                    .ecom-shopify__blog--post-informations-icon {
                        display: flex;
                    }
                    .ecom-shopify__blog--post-informations-icon svg {
                        width: 16px;
                        height: 16px;
                    }
                    .ecom-swiper-pagination-bullet:only-child {
                        opacity: none
                    }
                    .ecom-flex-center, .ecom-swiper-navigation {
                        display: flex;
                        align-items: center;
                    }
                    .ecom-swiper-navigation{
                        justify-content: center
                    }
                    .ecom-shopify__blog--post-informations-author-avatar {
                        width: 50px;
                    }
                    .ecom-swiper-navigation[data-navigator-type="combine"]{
                        justify-content: center
                    }
                    .ecom-shopify__blog--post-thumbnail {
                        display: flex;
                        position: relative;
                        overflow: hidden;
                    }

                    .ecom-shopify__blog--post-thumbnail img{
                            object-fit: cover;
                            display: block;
                            max-width: 100%;
                            top: 0;
                            left: 0;
                            height: 100% !important;
                            width: 100%;
                    }
                    .ecom-shopify__blog--post-tags ul li{
                        display:inline-flex;
                    }
                    .ecom-shopify__blog--post-tags ul {
                        display: flex;
                        flex-wrap:wrap;
                        gap: 12px;
                        margin: 0;
                        padding: 0;
                    }
                    /*.ecom-shoify__blog-pagination {
                        margin: 0;
                        padding: 0;
                        text-align: center;
                        list-style-type: none;
                        display: flex;
                        justify-content: center;
                        gap: 24px;
                        align-items: center;
                        margin-top: 32px;
                        color: #000;
                    }*/

                    .ecom-collection__pagination-navigation{
                        list-style: none;
                        display: flex;
                        gap: 10px;
                        justify-content: center;
                    }
                    .ecom-collection__pagination-navigation li a {
                        color: inherit;
                    }
                    .ecom-paginate-action {
                        display:flex;
                        gap:5px;
                    }
                    .ecom-prev,
                    .ecom-next,
                    .ecom-prev span,
                    .ecom-next span{
                        display:flex;
                    }
                    .ecom-paginate-action svg{
                        width:24px;
                        height:24px;
                    }
                    .ecom-shopify__blog--post-link{
                        text-decoration:none;
                        width:100%;
                        display:flex;
                    }
                    .ecom-pagination-item {
                        display: flex;
                    }
                    a.ecom-pagination-item:not(.ecom-paginate-action) {
                        text-decoration:inherit
                    }
                    .ecom-paginate-action{
                        text-decoration:none
                    }
                    .ecom-pagination-item.ecom-button-active{
                        pointer-events:none;
                    }
                    .ecom-swiper-controls:after
                    {
                        content:'';
                        display:none
                    }
                    .ecom-shopify__blog-wrapper {
                        display: flex;
                        flex-direction: column;
                    }
                    .ecom-shopify__blog-wrapper .ecom-shopify__blog-container{
                        width: 100%
                    }
                    .ecom-shopify__blog--posts.ecom-swiper-wrapper {
                        display: flex;
                        gap: 0;
                    }
                    .ecom-shopify__blog-wrapper .ecom-swiper-button-next:after,
                    .ecom-shopify__blog-wrapper .ecom-swiper-button-prev:after {
                        content: none;
                    }
                    .ecom-shopify__blog-wrapper .ecom-swiper-navigation[data-navigator-type="combine"] .ecom-swiper-button-next,
                    .ecom-shopify__blog-wrapper .ecom-swiper-navigation[data-navigator-type="combine"] .ecom-swiper-button-prev {
                        position: static;
                        margin: 0;
                    }
                    .ecom-shopify__blog-wrapper .ecom-swiper-button-next,
                    .ecom-shopify__blog-wrapper .ecom-swiper-button-prev {
                        border: 0;
                        background: transparent;
                        width: auto;
                        height: auto;
                        padding: 5px;
                        color: #444;
                    }
                    .ecom-swiper-navigation-position .ecom-swiper-button {
                        position: var(--ecom-position);
                    }
                    .ecom-swiper-navigation-position {
                        display: flex;
                    }
                    .ecom-swiper-navigation-position button {
                        margin: 0;
                    }
                    .ecom-shopify__blog-wrapper .ecom-swiper-pagination:not(.ecom-swiper-pagination-progressbar) {
                        position: relative;
                        display: flex;
                        flex-wrap: wrap;
                        align-items: center
                    }
                    .ecom-swiper-container-horizontal>.ecom-swiper-pagination-bullets{
                        width:auto;
                    }
                    .ecom-shopify__blog--post-title {
                        font-size: inherit;
                    }

                    .ecom-shopify__blog--post-link img{
                        object-fit: cover;
                        max-width: 100%;
                        object-position: center center;
                        transition: opacity .4s cubic-bezier(.25, .46, .45, .94);
                    }
                    .ecom-shopify__blog--post-group-4 {
                        flex-wrap: wrap;
                    }
                    .ecom-shopify__blog--post-group-4 > *{
                        display: inline-flex;
                        align-items: center;
                    }
                    .ecom-swiper-pagination-bullet{
                        opacity:1 !important;
                    }
                    .ecom-swiper-pagination-bullets.ecom-swiper-pagination{
                        display:flex;
                        width:100%;
                    }
                    .ecom-shopify__blog--post-link h2{
                        width:100%;
                    }
                    .ecom-shopify__blog--post.ecom-shopify__blog-vertical {
                        display: flex;
                        gap: 15px;
                    }
                    @media (max-width: 1023px) and (min-width: 768px) {
                        .ecom-swiper-navigation-position .ecom-swiper-button {
                            position: var(--ecom-position__tablet);
                        }
                    }
                    @media (max-width: 767px) {
                        .ecom-shopify__blog--post.ecom-shopify__blog-vertical {
                            flex-direction: column;
                        }
                        .ecom-shopify__blog--post .ecom-shopify__blog--post-thumbnail--img {
                            order: 0 !important;
                        }
                        .ecom-swiper-navigation-position .ecom-swiper-button {
                            position: var(--ecom-position__mobile);
                        }
                    }
                    .ecom-doing-load-blog .ecom-shopify__blog-container{
                        display: none;
                    }
                    .ecom-doing-load-blog .ecom-collection__product-loading{
                        display: block;
                    }
                    .ecom-shopify__blog--empty-text {
                        width: 100%;
                        padding: 20px;
                    }
                    .ecom-shopify__blog--posts.ecom-grid > .code-placeholder,
                    .ecom-shopify__blog--posts.ecom-grid > .ecom-shopify__blog--empty-text {
                        grid-column: 1 / -1;
                        width: 100%;
                    }
                    `;
        },

        javascript() {
            return function () {
                // Nút pause autoplay (WCAG 2.2.2). Đọc $container.swiper lúc click
                // nên không phụ thuộc thứ tự init của slider bên dưới.
                var $ecomAptg = this.$el && this.$el.querySelector('.ecom-swiper-autoplay-toggle');
                if ($ecomAptg && !$ecomAptg.getAttribute('data-ecom-bound')) {
                    $ecomAptg.setAttribute('data-ecom-bound', '1');
                    var $ecomAptgBox = this.$el.querySelector('.ecom-swiper-container');
                    $ecomAptg.addEventListener('click', function () {
                        var sw = $ecomAptgBox && $ecomAptgBox.swiper;
                        if (!sw || !sw.autoplay) return;
                        if (sw.autoplay.running) {
                            // stop() chứ không pause(): pause() sẽ bị resume() của
                            // pauseOnMouseEnter bật lại, người dùng bấm dừng phải dừng hẳn.
                            sw.autoplay.stop();
                            $ecomAptg.setAttribute('data-state', 'paused');
                            $ecomAptg.setAttribute('aria-label', $ecomAptg.getAttribute('data-label-play'));
                        } else {
                            sw.autoplay.start();
                            $ecomAptg.setAttribute('data-state', 'playing');
                            $ecomAptg.setAttribute('aria-label', $ecomAptg.getAttribute('data-label-pause'));
                        }
                    });
                }
                if (this.settings.layout === 'slider') {
                    let $el = this.$el, isLive = this.isLive;
                    let type_pagination = 'bullets';
                    if(this.settings.slider_pagination_style === 'progress') type_pagination = 'progressbar';
                    if(!$el) return;
                    let $container = $el.querySelector('.ecom-shopify__blog-container');
                    if(!$container) return;
                    const _settings = this.settings;
                    const _initSwiper = function() {
                        if(!(window.EComposer && typeof window.EComposer.buildSwiperConfig === 'function')) {
                            let _r = 0;
                            const _t = setInterval(function() {
                                _r++;
                                if(window.EComposer && typeof window.EComposer.buildSwiperConfig === 'function') { clearInterval(_t); _initSwiper(); }
                                else if(_r >= 75) clearInterval(_t);
                            }, 200);
                            return;
                        }
                        let optionSwiper = window.EComposer.buildSwiperConfig(_settings);
                        optionSwiper.pagination = {
                            el: $el.querySelector('.ecom-swiper-pagination'),
                            type: type_pagination,
                            clickable: true
                        };
                        optionSwiper.allowTouchMove = isLive;
                        optionSwiper.navigation = {
                            nextEl: $el.querySelector('.ecom-swiper-button-next'),
                            prevEl: $el.querySelector('.ecom-swiper-button-prev')
                        };
                        new window.EComSwiper($container, optionSwiper);
                    };
                    _initSwiper();

                }
                //pagination
                if(this.settings.use_ajax){
                    if(this.isLive){
                        const $el = this.$el;
                        if(!$el) return;
                        const main_wrapper = $el.querySelector(".ecom-shopify__blog-wrapper");
                        const handleClickNumberPages = function(e){
                            e.preventDefault();
                            const url = this.dataset.get;
                            const wrapper = this.closest('.ecom-sections[data-section-id]');
                            if(!url || !wrapper || !wrapper.dataset.sectionId) return;
                            const section_id = wrapper.dataset.sectionId;
                            const fetch_url = `${url}&section_id=${section_id}`;
                            handleLoadBlog(fetch_url,wrapper);
                            main_wrapper.scrollIntoView();
                        }
                        const btnNum = $el.querySelectorAll('.ecom-pagination-item');
                        btnNum.forEach((element)=>{
                            element.addEventListener('click',handleClickNumberPages);
                        });
                        const handleLoadBlog = function(fetch_url, wrapper){
                            const loadBlog = async function(url){
                                const response = await fetch(url,{
                                    method: 'GET',
                                    cache: 'no-cache',
                                    headers: {
                                        'Content-Type': 'text/html'
                                    },
                                });

                                return response.text();
                            }
                            wrapper.classList.add('ecom-doing-load-blog');
                            loadBlog(fetch_url).then(function(data){
                                const oldBlogs = $el.querySelectorAll(".ecom-shopify__blog--post");
                                oldBlogs.forEach(function(element){
                                    element.remove();
                                });
                                const dom = document.createElement('div');
                                dom.innerHTML = data;
                                const blogs_item = dom.querySelector('.ecom-shopify__blog--posts');
                                if(!blogs_item) return;
                                const wrapper_blogs = wrapper.querySelector('.ecom-shopify__blog--posts');
                                const pagination = wrapper.querySelector('.ecom-pagination-navigation.ecom-collection__pagination-navigation');
                                while(blogs_item.firstChild){
                                    wrapper_blogs.appendChild(blogs_item.firstChild);
                                }
                                blogs_item.parentNode.removeChild(blogs_item);
                                const paginate = dom.querySelector('.ecom-pagination-navigation.ecom-collection__pagination-navigation');
                                if(paginate){
                                    pagination.innerHTML = paginate.innerHTML;
                                    const btnNum = $el.querySelectorAll('.ecom-pagination-item');
                                    btnNum.forEach((element)=>{
                                        element.addEventListener('click',handleClickNumberPages);
                                    });
                                }
                            })
                            .finally(function(){
                                wrapper.classList.remove('ecom-doing-load-blog')
                            })
                        }
                    }
                }
            };
        },


        items_on_row() {
            return this.data.settings && this.data.settings.items_on_row
                ? this.data.settings.items_on_row
                : 4;
        },

        layout() {
            return this.data.settings && this.data.settings.layout
                ? this.data.settings.layout
                : 'grid';
        },

        articlePagination() {
            if ( ['featured', 'related'].includes(this.data.template) || !this.data?.settings?.enable_pagination || this.data?.settings?.layout !== 'grid' ) {
                return '';
            }

            if (this.canUseCustomLiquidForCSR) {
                return this.data?.settings?.show_preview_pagination ? `
                    {%- if blog.articles_count > 0 -%}
                        <nav role="navigation">
                            <ol class="ecom-pagination-navigation ecom-collection__pagination-navigation">
                                <li class="ecom-prev" style="${ this.data.settings.pagination_style === 'block'? 'margin-right:auto': ''}">
                                    <a class="ecom-pagination-item ecom-paginate-action" data-get="{{ paginate.previous.url }}" href="{{ paginate.previous.url }}">
                                        ${['icon', 'text_icon'].includes(this.data.settings?.number_type) ? `<span class="ecom-paginate-action--icon">${this.data.settings.icon_prev_page || ''}</span>` : '' }
                                        ${this.data.settings.number_type !== 'icon'? this.lang(this.data.settings.text_prev_page,'prev_page'): ''}
                                    </a>
                                </li>
                                ${[1, 2, 3].map(i => `
                                    <li class="ecom-pagination-item ${i === 1 ? 'ecom-button-active' : ''}">
                                        <a href="/" title="${i}">
                                            ${i}
                                        </a>
                                    </li>
                                `).join('')}
                                <li class="ecom-pagination-item ecom-next" style="${this.data.settings?.pagination_style === 'block' ? 'margin-left:auto' : ''}">
                                    <a class="ecom-paginate-action" href="/">
                                        ${this.data.settings?.number_type !== 'icon' ? this.lang(this.data.settings?.text_next_page, 'next_page') : ''}
                                        ${['icon', 'text_icon'].includes(this.data.settings?.number_type) ? `<span class="ecom-paginate-action--icon">${this.data.settings?.icon_next_page || ''}</span>` : ''}
                                    </a>
                                </li>
                             </ol>
                        </nav>
                    {%- endif -%}
                ` : '';
            }

            return `
             {%- if blog -%}
                {%- paginate blog.articles by limit -%}
                    {%- if paginate.pages > 1 -%}
                        <nav role="navigation">
                            <ol class="ecom-pagination-navigation ecom-collection__pagination-navigation">
                                {%- if paginate.previous -%}
                                    <li class="ecom-prev" style="${
                                    this.data.settings.pagination_style === 'block'? 'margin-right:auto': ''}">
                                        <a class="ecom-pagination-item ecom-paginate-action" data-get="{{ paginate.previous.url }}" href="{{ paginate.previous.url }}">
                                        ${this.data.settings.number_type === 'icon' || this.data.settings.number_type === 'text_icon'
                                        ? `<span class="ecom-paginate-action--icon">${this.data.settings.icon_prev_page || ''}</span>`
                                        : ''
                                        }
                                        ${this.data.settings.number_type !== 'icon'? this.lang(this.data.settings.text_prev_page,'prev_page'): ''}
                                        </a>
                                    </li>
                                {%- else -%}
                                    <li class="ecom-pagination-item ecom-prev ecom-paginate-action disabled" style="${
                                    this.data.settings.pagination_style === 'block'? 'margin-right:auto': ''}">
                                        ${ this.data.settings.number_type === 'icon' || this.data.settings.number_type ==='text_icon'
                                        ?  `<span class="ecom-paginate-action--icon">${this.data.settings.icon_prev_page || ''}</span>`
                                        : ''
                                        }
                                        ${this.data.settings.number_type !== 'icon'? this.lang(this.data.settings.text_prev_page,'prev_page'): ''}
                                    </li>
                                {%- endif -%}

                                {%- for part in paginate.parts -%}
                                    {%- if part.is_link -%}
                                        <li>
                                            <a class="ecom-pagination-item" data-get="{{part.url}}" href="{{ part.url }}" title="{{ part.title }}">
                                                {{ part.title }}
                                            </a>
                                        </li>
                                    {%- else -%}
                                        {%- if part.title == paginate.current_page -%}
                                        <li class="ecom-pagination-item ecom-button-active" aria-current="page">
                                            {{ part.title }}
                                        </li>
                                        {%- else -%}
                                        <li class="ecom-pagination-item">
                                            {{ part.title }}
                                        </li>
                                        {%- endif -%}
                                    {%- endif -%}
                                {%- endfor -%}

                                {%- if paginate.next -%}
                                    <li class="ecom-next" style="${
                                    this.data.settings.pagination_style === 'block'? 'margin-left:auto': ''}">
                                        <a class="ecom-pagination-item ecom-paginate-action" data-get="{{ paginate.next.url }}" href="{{ paginate.next.url }}">

                                            ${this.data.settings.number_type !=='icon' ? this.lang(this.data.settings?.text_next_page,'next_page'): '' }

                                            ${this.data.settings.number_type ==='icon' ||this.data.settings.number_type === 'text_icon'
                                            ? `<span class="ecom-paginate-action--icon">${this.data.settings.icon_next_page || ''}</span>`
                                            : ''
                                            }
                                        </a>
                                    </li>
                                    {%- else -%}
                                    <li class="ecom-pagination-item ecom-next ecom-paginate-action ecom-collection__pagination--disabled" style="${
                                    this.data.settings.pagination_style === 'block'? 'margin-left:auto': ''}">
                                        ${this.data.settings.number_type !== 'icon' ? this.lang(this.data.settings.text_next_page,'next_page') : ''}
                                        ${this.data.settings.number_type === 'icon' || this.data.settings.number_type === 'text_icon'
                                            ? `<span class="ecom-paginate-action--icon">${this.data.settings.icon_next_page || ''}</span>`
                                            : ''
                                        }
                                    </li>
                                {%- endif -%}
                            </ol>
                        </nav>
                    {%- endif -%}
                {%- endpaginate -%}
            {%- endif -%}
            `
        },
        blogIterationTemplate() {
            if (this.canUseCustomLiquidForCSR && this?.data?.template === "featured") return "{% for blog in blogs %}";

            return this.selected_blog !== ''
                ? ` {%- capture stringBlog -%}${this.selected_blog}{%-  endcapture-%}
                    {% assign blog_handles = stringBlog | split: ',' %}
                    {% for blogItem in blog_handles %}
                    {%- assign blog = blogs[blogItem] -%}
                    {% if blog == null %}{% continue %}{% endif %}
                    {% if blog.articles.size == 0 %}{% continue %}{% endif %}`
                : ""
        },
        liquids() {
            const emptyState = this.data.settings?.empty_articles_text
                ? `div class="ecom-shopify__blog--empty-text">${this.data.settings.empty_articles_text}</div>`
                : this.exporting
                    ? ""
                    : ` <div class="code-placeholder" style="width:100%">
                            <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                                <polyline points="16 18 22 12 16 6"></polyline>
                                <polyline points="8 6 2 12 8 18"></polyline>
