                            <span>Blog has no articles. Please add articles or select a different blog in settings.</span>
                        </div>`
            return {
                blog: {
                    code: `
                        {% if tmp_block == nil or tmp_block == blank %}
                            {% assign tmp_block = blog %}
                        {% endif %}
                        {%- capture stringBlog -%}${this.selected_blog}{%- endcapture -%}
                        {% assign blog_handles = stringBlog | split: ',' %}
                        ${this.data.template === 'featured' && !this.selected_blog ? `{% assign blog = nil %}` : ''}
                        <div class="${this.layout === 'slider' ? 'ecom-swiper-wrapper' : 'ecom-grid' } ecom-shopify__blog--posts" style="${this.layout === 'slider' ? '' : 'display:grid'}"${this.exporting === true && this.data.settings?.scroll_reveal_items && this.layout !== 'slider' ? ` data-ec-sr-items="${this.data.settings.scroll_reveal_items_type || 'fade-up'}" data-ec-sr-delay="${this.data.settings.scroll_reveal_items_delay || 100}"` : ''}>
                            {% assign count = 1 %}
                            ${this.canUseCustomLiquidForCSR && this.data.template === 'featured' ? `{% if blogs == blank %}${emptyState}{% else %}` : ''}
                            ${this.blogIterationTemplate}
                                {% if blog != null %}
                                    {%- capture limit -%}${this.data.settings?.limit? this.data.settings.limit : 20 }{%-endcapture-%}
                                    {% assign limit = limit | plus: 0 %}
                                    {% assign tmp_article = article %}
                                    ${this.data.template === 'related' ? `{% assign limit = limit %}`:''}
                                    {% assign ecom_articles_count = blog.articles.size %}
                                    ${this.data.template === 'blog' ? `{%- paginate blog.articles by limit -%}` : ''}
                                    {% for article in blog.articles %}
                                        {% if count > limit %}{% break%}{% endif %}
                                        {% assign count =  count | plus: 1%}
                                        ${this.data.template === 'related' ? `{% if tmp_article  and article.id == tmp_article.id %}{% assign limit = limit | plus: 1 %}{% continue %}{% endif %}` : ``}
                                        <div class="ecom-shopify__blog--post${this.layout === 'slider' ? ' ecom-swiper-slide' : ''}${this.is_horizontal_content ? ' ecom-shopify__blog-vertical' : ``}"${this.exporting === true && this.data.settings?.scroll_reveal_items && this.layout !== 'slider' ? ` data-ec-sr-item` : ''}>
                                            ${this.is_horizontal_content
                                                ? `${this.check('thumbnail') 
                                                    ? ` <div class="ecom-shopify__blog--post-thumbnail--img">
                                                            <div class="ecom-shopify__blog--post-thumbnail ecom-image-align {% if article.image == blank %} ecom-shopify__blog--post-no-thumbnail{% endif %}">
                                                                {%- if article.image -%}
                                                                {%- liquid
                                                                    assign featured_media_aspect_ratio = article.featured_media.aspect_ratio

                                                                    if article.featured_media.aspect_ratio == nil
                                                                        assign featured_media_aspect_ratio = 1
                                                                    endif
                                                                -%}
                                                                        <a style="text-decoration:none" href="{{article.url}}" class="ecom-shopify__blog--post-link ecom-image-default"  data-blog-handle="{{article.handle}}">
                                                                        <img srcset="
                                                                            {%- if article.image.src.width >= 533 -%}{{ article.image.src | image_url: width: 533 }} 533w,{%- endif -%}
                                                                            {%- if article.image.src.width >= 720 -%}{{ article.image.src | image_url: width: 720 }} 720w,{%- endif -%}
                                                                            {%- if article.image.src.width >= 940 -%}{{ article.image.src | image_url: width: 940 }} 940w,{%- endif -%}
                                                                            {%- if article.image.src.width >= 1066 -%}{{ article.image.src | image_url: width: 1066 }} 1066w{%- endif -%}"
                                                                            src="{{ article.image.src | image_url: width: 533 }}"
                                                                            sizes="(min-width: 1100px) 535px, (min-width: 750px) calc((100vw - 130px) / 2), calc((100vw - 50px) / 2)"
                                                                            alt="{{ article.image.src.alt | escape }}"
                                                                            width="{{ article.image.width }}"
                                                                            height="{{ article.image.height }}"
                                                                            loading="lazy"
                                                                        >
                                                                    </a>
                                                                    {%- endif -%}
                                                            </div>
                                                        </div>
                                                ` : ''}
                                                <div class="ecom-shopify__blog--posts-details">
                                            ` : ``}
                                            ${this.attributes.map((attr) => {
                                                switch (attr.type) {
                                                    case 'title':
                                                        var tag = attr.settings?.tag ? attr.settings?.tag: 'h2';
                                                        return `<a href="{{article.url }}" class="ecom-shopify__blog--post-link"  data-blog-handle="{{article.handle}}"><${tag} class="ecom-shopify__blog--post-title">{{article.title}}</${tag}></a>`;
                                                    case 'thumbnail':
                                                        if(!this.is_horizontal_content) {
                                                            return `
                                                                <div class="ecom-shopify__blog--post-thumbnail--img">
                                                                    <div class="ecom-shopify__blog--post-thumbnail ecom-image-align {% if article.image == blank %} ecom-shopify__blog--post-no-thumbnail{% endif %}">
                                                                        {%- if article.image -%}
                                                                        {%- liquid
                                                                            assign featured_media_aspect_ratio = article.featured_media.aspect_ratio

                                                                            if article.featured_media.aspect_ratio == nil
                                                                                assign featured_media_aspect_ratio = 1
                                                                            endif
                                                                        -%}
                                                                                <a style="text-decoration:none" href="{{article.url }}" class="ecom-shopify__blog--post-link ecom-image-default"  data-blog-handle="{{article.handle}}">
                                                                                <img srcset="
                                                                                    {%- if article.image.src.width >= 533 -%}{{ article.image.src | image_url: width: 533 }} 533w,{%- endif -%}
                                                                                    {%- if article.image.src.width >= 720 -%}{{ article.image.src | image_url: width: 720 }} 720w,{%- endif -%}
                                                                                    {%- if article.image.src.width >= 940 -%}{{ article.image.src | image_url: width: 940 }} 940w,{%- endif -%}
                                                                                    {%- if article.image.src.width >= 1066 -%}{{ article.image.src | image_url: width: 1066 }} 1066w{%- endif -%}"
                                                                                    src="{{ article.image.src | image_url: width: 533 }}"
                                                                                    sizes="(min-width: 1100px) 535px, (min-width: 750px) calc((100vw - 130px) / 2), calc((100vw - 50px) / 2)"
                                                                                    alt="{{ article.image.src.alt | escape }}"
                                                                                    width="{{ article.image.width }}"
                                                                                    height="{{ article.image.height }}"
                                                                                    loading="lazy"
                                                                                >
                                                                            </a>
                                                                            {%- endif -%}
                                                                    </div>
                                                                </div>
                                                            `;
                                                        } else {
                                                            return '';
                                                        }
                                                    case 'excerpt':
                                                        var limit = attr.settings?.limit_words ?? 12;
                                                        return `
                                                        <div class="ecom-shopify__blog--post-excerpt">
                                                            {{ article.excerpt_or_content | strip_html | truncatewords: ${limit}}}
                                                        </div>
                                                    `;
                                                    case 'author':
                                                        return `
                                                        <div class="ecom-shopify__blog--post-author">
                                                            {% assign article_author = article.author %}
                                                        ${this.lang('By {{article_author}}','post_by_author',{article_author: 'article_author' })}
                                                        </div>
                                                    `;
                                                    case 'category':
                                                        return `
                                                            <div class="ecom-shopify__blog--post-category">
                                                                <a href="{{blog.url}}" alt="{{blog.title}}">{{blog.title}}</a>
                                                            </div>
                                                        `;
                                                    case 'tags':
                                                        return `
                                                        <div class="ecom-shopify__blog--post-tags ecom-shopify__blog--post-informations">
                                                            {% if article.tags.size %}
                                                                <ul>
                                                                    {% for tag in article.tags %}
                                                                        <li>
                                                                            <a href="/blogs/{{blog.handle}}/tagged/{{tag | handleize }}">{{ tag }}</a>
                                                                        </li>
                                                                    {% endfor %}
                                                                </ul>
                                                            {% endif %}
                                                        </div>
                                                    `;

                                                    case 'meta':
                                                        var format = attr?.settings?.date_format &&  attr?.settings?.date_format !== 'day_first'
                                                        ? `format: '${attr?.settings?.date_format}'`
                                                        : attr?.settings?.date_format &&  attr?.settings?.date_format === 'day_first'
                                                        ?`'%e/%-m/%Y'`
                                                        :`format: 'date'`;
                                                        var layout = attr?.settings?.meta_layout ?? 'one';
                                                        // eslint-disable-next-line no-var
                                                        var templates = {
                                                            one: [
                                                                'group_meta_1'
                                                            ],
                                                            two: [
                                                                'group_meta_2'
                                                            ],
                                                            three: [
                                                                'group_meta_3'
                                                            ],
                                                            four:[
                                                                'group_meta_4',
                                                                'comments_count'
                                                            ],
                                                            five:[
                                                                'comments_count'
                                                            ]
                                                        };
                                                        // if(attr?.settings?.hide_author) {
                                                        //     templates[layout] = templates[layout].filter(type => type != 'author');
                                                        // }
                                                        // if(attr?.settings?.hide_time) {
                                                        //     templates[layout] = templates[layout].filter(type => type != 'published_at');
                                                        // }
                                                        // if(attr?.settings?.hide_comment_count) {
                                                        //     templates[layout] = templates[layout].filter(type => type != 'comments_count');
                                                        // }

                                                        // eslint-disable-next-line no-var
                                                        let author = `<div class="ecom-shopify__blog--post-author ecom-shopify__blog--post-informations">
                                                                {% assign article_author = article.author %}
                                                                ${attr?.settings?.icon_author
                                                                    ? `
                                                                        <span class="ecom-shopify__blog--post-informations-icon">${attr?.settings?.icon_author}</span>
                                                                    `
                                                                    : ''
                                                                }
                                                                ${!attr?.settings?.icon_author && attr?.settings?.avatar_type != 'off'
                                                                    ? `
                                                                        ${attr?.settings?.avatar_type == 'shopify'
                                                                            ? `
                                                                                {%- if article.user.image -%}
                                                                                    <div class="ecom-shopify__blog--post-informations-author-avatar">
                                                                                        <div class="ecom-image-default">
                                                                                            <img src="{{ article.user.image | image_url: width: 2048 }}" alt="{{ article.author }}">
                                                                                        </div>
                                                                                    </div>
                                                                                {%- else -%}
                                                                                    <div class="ecom-shopify__blog--post-informations-author-avatar">
                                                                                        <div class="ecom-image-default">
                                                                                            ${attr?.settings?.image_author?.url
                                                                                                ? `
                                                                                                    <img src="${attr?.settings?.image_author?.url}" alt="{{ article.author }}"/>
                                                                                                `
                                                                                                : ``
                                                                                            }
                                                                                        </div>
                                                                                    </div>
                                                                                {%- endif -%}
                                                                            `
                                                                            : ''
                                                                        }
                                                                        ${attr?.settings?.avatar_type == 'gavatar'
                                                                            ? `
                                                                                {%- if article.user.email -%}
                                                                                    <div class="ecom-shopify__blog--post-informations-author-avatar">
                                                                                        <div class="ecom-image-default">
                                                                                            <img src="https://www.gravatar.com/avatar/{{ article.user.email | downcase | md5 }}" alt="{{ article.author }}">
                                                                                        </div>
                                                                                    </div>
                                                                                {%- endif -%}
                                                                            `
                                                                            : ''
                                                                        }
                                                                    `
                                                                    : ''
                                                                }
                                                                ${this.lang(`${attr?.settings?.hide_by_text ? '' : attr?.settings?.by_text ? attr.settings.by_text + ' ' : 'By '}{{article_author}}`,'post_by_author',{article_author: 'article_author' })}${attr?.settings?.hide_in_text ? '' : ' '}
                                                            </div>`,
                                                            comments_count = attr?.settings?.hide_comment_count ? '' : `
                                                                <div class="ecom-shopify__blog--post-comments_count ecom-shopify__blog--post-informations">
                                                                    {% if article.comments_enabled? %}
                                                                        ${attr?.settings?.icon_comment ? `<span class="ecom-shopify__blog--post-informations-icon">${attr?.settings?.icon_comment}</span> ` : '' }
                                                                        {% assign comments_count = article.comments_count %}
                                                                        {% assign comment_count = article.comments_count %}
                                                                        {% if article.comments_count == 1%}
                                                                            <span>
                                                                                ${this.lang(attr?.settings?.comment_count_text ??'','comment_count_text',{comment_count: 'article.comments_count'})}
                                                                            </span>
                                                                    {% else %}
                                                                            <span>
                                                                                ${this.lang(attr?.settings?.comments_count_text ??'','comments_count_text',{comments_count:'article.comments_count'})}
                                                                            </span>
                                                                                {% endif %}
                                                                    {% endif %}
                                                                </div>`,
                                                            published_at = `
                                                                <div class="ecom-shopify__blog--post-published-at ecom-shopify__blog--post-informations">
                                                                    {% assign published_at = ${attr?.settings?.date_type === 'updated_at' ? `article.updated_at` : `article.published_at`} | time_tag: ${format}  %}
                                                                    ${attr?.settings?.icon_time
                                                                        ? `
                                                                            <span class="ecom-shopify__blog--post-informations-icon">${attr?.settings?.icon_time}</span>
                                                                        `
                                                                        : ''
                                                                    }
                                                                    <span>${this.lang(`${attr?.settings?.hide_in_text ? '' :  attr?.settings?.in_text ? attr.settings.in_text + ' ' : 'in '}{{published_at}}`, 'post_published_at',{ published_at: 'published_at'})}</span>
                                                                </div>`
                                                        var metas = {
                                                            comments_count: attr?.settings?.hide_comment_count ? '' : `
                                                                    <div class="ecom-shopify__blog--post-comments_count ecom-shopify__blog--post-informations">
                                                                        {% if article.comments_enabled? %}
                                                                            ${attr?.settings?.icon_comment
                                                                                ? `
                                                                                    <span class="ecom-shopify__blog--post-informations-icon">${attr?.settings?.icon_comment}</span>
                                                                                `
                                                                                : ''
                                                                            }
                                                                            {% assign comments_count = article.comments_count %}
                                                                            {% assign comment_count = article.comments_count %}
                                                                            {% if article.comments_count == 1%}
                                                                                <span>
                                                                                    ${this.lang(attr?.settings?.comment_count_text ??'','comment_count_text',{comment_count: 'article.comments_count'})}
                                                                                </span>
                                                                            {% else %}
                                                                                <span>
                                                                                    ${this.lang(attr?.settings?.comments_count_text ??'','comments_count_text',{comments_count:'article.comments_count'})}
                                                                                </span>
                                                                                    {% endif %}
                                                                            {% endif %}
                                                                            </div>`
                                                            ,
                                                            group_meta_4:`
                                                                <div class="ecom-shopify__blog--post-group-4 ecom-flex ecom-al_center ${attr?.settings?.layout4_meta_aligment}">
                                                                    ${attr?.settings?.hide_author ? '' : author }
                                                                    ${attr?.settings?.hide_time ? '' : published_at }
                                                                </div>
                                                            `,
                                                            group_meta_1: `
                                                                <div class="ecom-shopify__blog--post-group-1 ecom-flex ecom-al_center ${attr?.settings?.layout4_meta_aligment}">
                                                                    ${attr?.settings?.hide_author ? '' : author }
                                                                    ${attr?.settings?.hide_time ? '' : published_at }
                                                                    ${attr?.settings?.hide_comment_count ? '' : comments_count}
                                                                </div>
                                                            `,
                                                            group_meta_2: `
                                                                <div class="ecom-shopify__blog--post-group-2 ecom-flex ecom-al_center ${attr?.settings?.layout4_meta_aligment}">
                                                                    ${attr?.settings?.hide_time ? '' : published_at }
                                                                    ${attr?.settings?.hide_author ? '' : author }
                                                                    ${attr?.settings?.hide_comment_count ? '' : comments_count}
                                                                </div>
                                                            `,
                                                            group_meta_3: `
                                                                <div class="ecom-shopify__blog--post-group-3 ecom-flex ecom-al_center ${attr?.settings?.layout4_meta_aligment}">
                                                                    ${attr?.settings?.hide_comment_count ? '' : comments_count}
                                                                    ${attr?.settings?.hide_author ? '' : author }
                                                                    ${attr?.settings?.hide_time ? '' : published_at }
                                                                </div>
                                                            `
                                                        };

                                                        var html = '';
                                                        for (var tmp of templates[layout]) {
                                                            html += metas[tmp];
                                                        }
                                                        return html;

                                                    case 'link':
                                                        return `
                                                            <div class="ecom-shopify__blog--post-link-wrapper">
                                                                <a href="{{article.url }}" class="ecom-shopify__blog--post-link-btn ecom-flex ecom-al_center ecom-fl_center"  data-blog-handle="{{article.handle}}">
                                                                    ${attr?.settings?.text ? `<span>${this.lang(attr?.settings?.text, "link_text")}</span>` : ``}
                                                                    ${attr?.settings?.icon ? `<span class="ecom__element--button-icon ecom-flex ecom-al_center ecom-fl_center">${attr?.settings?.icon}</span>` : ``}
                                                                </a>
                                                            </div>
                                                        `;

                                                    default:
                                                        return '';
                                                    }
                                            }).join('')}
                                            ${this.is_horizontal_content ? '</div>' : ``}
                                        </div>
                                    {% endfor %}
                                ${this.data.template === 'blog' ? `{%- endpaginate -%}` : ''}
                                ${this.selected_blog === '' ? `
                                {% if ecom_articles_count == 0 %}
                                    ${this.data.settings?.empty_articles_text
                                        ? `<div class="ecom-shopify__blog--empty-text">${this.data.settings.empty_articles_text}</div>`
                                        : this.exporting
                                            ? ``
                                            : `<div class="code-placeholder" style="width:100%">
                                                <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                                                    <polyline points="16 18 22 12 16 6"></polyline>
                                                    <polyline points="8 6 2 12 8 18"></polyline>
                                                </svg>
                                                <span>Blog has no articles. Please add articles or select a different blog in settings.</span>
                                            </div>`
                                    }
                                {% endif %}
                                ` : ''}
                            {% else %}
                                ${this.selected_blog === ''
                                    ? (this.data.settings?.empty_articles_text
                                        ? `<div class="ecom-shopify__blog--empty-text">${this.data.settings.empty_articles_text}</div>`
                                        : this.exporting
                                            ? ``
                                            : `<div class="code-placeholder" style="width:100%">
                                            <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                                                <polyline points="16 18 22 12 16 6"></polyline>
                                                <polyline points="8 6 2 12 8 18"></polyline>
                                            </svg>
                                            <span>Please select the Blog in the settings on the right sidebar to display it</span>
                                        </div>`)
                                    : ''
                                }
                            {% endif %}
                            ${this.blogIterationTemplate ? `{% endfor %}` : ''}
                            ${this.selected_blog !== '' ? `{% if count == 1 %} ${emptyState} {% endif %}` : ''}
                            ${this.canUseCustomLiquidForCSR && this.data.template === 'featured' ? `{% endif %}` : ''}
                        </div>
                        ${this.articlePagination}
                        {% unless tmp_block == nil and tmp_block == blank %}
                            {% assign blog = tmp_block %}
                        {% endunless %}
                        {% unless tmp_article == nil and tmp_article == blank %}
                            {% assign article = tmp_article %}
                        {% endunless %}
                    `,
                    preview: `
                        <div class="ecom-skeleton-item">
                            <div class="ecom-skeleton-col-4">
                                <div class="ecom-skeleton-row">
                                    <div class="ecom-skeleton-col-10 ecom-skeleton-big"></div>
                                    <div class="ecom-skeleton-col-8 ecom-skeleton-big"></div>
                                </div>
                            </div>
                            <div class="ecom-skeleton-col-4">
                                <div class="ecom-skeleton-row">
                                    <div class="ecom-skeleton-col-10 ecom-skeleton-big"></div>
                                    <div class="ecom-skeleton-col-8 ecom-skeleton-big"></div>
                                </div>
                            </div>
                            <div class="ecom-skeleton-col-4">
                                <div class="ecom-skeleton-row">
                                    <div class="ecom-skeleton-col-10 ecom-skeleton-big"></div>
                                    <div class="ecom-skeleton-col-8 ecom-skeleton-big"></div>
                                </div>
                            </div>
                        </div>
                    `
                }
            };
        },

        requestShopifyType() {
            if(this.data.template === 'featured' )
            {
                return {};
            }
            if(this.data.template === 'featured' || this.data.template === 'related')
            {
                return {
                    shopify_type: 'article'
                };
            }
            return {
                shopify_type: 'blog'
            };
        },

        selected_blog() {
            const blogs = this.data.settings.blog ?? [];
            let handles = '';
            if(blogs.length) {
                blogs.forEach(function (blog, index) {
                    handles += blog.value
                    if(index != blogs.length - 1) handles += ',';
                })
                return handles;
            }
            return '';
            // return this.data && this.data.settings && this.data.settings.blog
            //     ? this.data.settings.blog.value
            //     : '';
        },
        is_horizontal_content() {
            return this.data && this.data.settings && this.data.settings.content_layout == 'horizontal'
        },

        settings() {
            let settings = [
                {
                    group_title: this.$t('general'),
                    params: [
                        {
                            type: 'popup',
                            label: this.$t('layout'),
                            name: 'layout',
                            options: {
                                type: 'dropdown',
                                preview: 'title',
                                values: {
                                    grid: this.$t('grid'),
                                    slider: this.$t('slider'),
                                },
                                default: false
                            }
                        },
                        {
                            type: 'popup',
                            label: this.$t('content_layout'),
                            name: 'content_layout',
                            options: {
                                type: 'dropdown',
                                preview: 'title',
                                values: {
                                    horizontal: this.$t('horizontal'),
                                    vertical: this.$t('vertical'),
                                },
                                default: false
                            }
                        },
                        {
                            type: 'choose',
                            label: this.$t('image_thumbnail_position'),
                            name: 'image_thumbnail_position',
                            options: {
                                type: 'align-x',
                                values: [-1, 1],
                                visible: {
                                    keep_data: false,
                                    condition: (data) => {
                                        return data['content_layout'] == 'horizontal';
                                    }
                                }
                            },
                            css:{
                                selector:' .ecom-shopify__blog--post-thumbnail--img',
                                properties:{
                                    order:''
                                }
                            }
                        },
                        {
                            type: 'number',
                            name: 'limit',
                            label: this.$t('maximum_blog_posts_to_show'),
                            options: {
                                min: 1,
                                max: ['blog', 'article', 'post'].includes(this.params?.page) ? 200 : 50
                            }
                        },
                        {
                            type: 'text',
                            name: 'empty_articles_text',
                            label: this.$t('empty_articles_text'),
                            options: {
                                placeholder: this.$t('no_posts_found')
                            }
                        },
                        {
                            type: 'group',
                            label: this.$t('select_attributes_to_show'),
                            name: 'attributes',
                            params: [
                                {
                                    type: 'title',
                                    name: this.$t('title'),
                                    max: 1,
                                    settings: [
                                        {
                                            type: 'popup',
                                            label: this.$t('heading_tag'),
                                            name: 'tag',
                                            options: {
                                                type: 'dropdown',
                                                preview:'title',
                                                values: {
