            return this.data.settings?.slider_navigation_layout === 'neo_full' ||
                    this.data.settings?.slider_navigation_layout === 'neo_navigator' ||
                    this.data.settings?.slider_navigation_layout === 'classic_full' ||
                    this.data.settings?.slider_navigation_layout === 'navigation';
        },
        isPagination() {
            return this.data.settings?.slider_navigation_layout === 'neo_full' ||
                    this.data.settings?.slider_navigation_layout === 'classic_full' ||
                    this.data.settings?.slider_navigation_layout === 'pagination';
        },
        style() {
            let style = [
                this.check('thumbnail') ? {
                    group_alias:'image',
                    options:{
                        selector: ' .ecom-shopify__blog--post-thumbnail--img .ecom-image-default',
                        group_name: 'blog_articles_img',
                        group_title: this.$t('image'),
                    },
                    modify:{
                        params:[
                            {
                                position:0,
                                fields:{
                                    alias:'justify-content',
                                    options:{
                                        label: this.$t('alignment'),
                                        css:{
                                            selector:'root .ecom-image-align'
                                        }
                                    }
                                }
                            },
                            {
                                position:20,
                                fields:{
                                    alias:'spacing',
                                    options:{
                                        css:{
                                            selector:'root .ecom-image-align'
                                        }
                                    }
                                }
                            }
                        ]
                    }
                } : null,
                this.check('title') ? {
                    group_alias:'text:hover',
                    options:{
                        selector: ' .ecom-shopify__blog--post-link:not(.ecom-image-default) > .ecom-shopify__blog--post-title',
                        group_name: 'blog_articles_title',
                        group_title: this.$t('title'),
                    },
                    modify:{
                        params:{
                            position:30,
                            fields:{
                                alias:'spacing'
                            }
                        }
                    }
                } : null,
                this.check('excerpt') ? {
                    group_alias:'text:spacing',
                    options:{
                        selector: ' .ecom-shopify__blog--post-excerpt',
                        group_name: 'blog_articles_description',
                        group_title: this.$t('description'),
                    }
                } : null,
                this.check('tags') ? {
                    group_alias:'button',
                    options:{
                        selector: ' .ecom-shopify__blog--post-tags li a',
                        group_name: 'blog_articles_tags',
                        group_title: this.$t('tags'),
                    },
                     modify:{
                        params:[
                            {
                                position:0,
                                fields:{
                                    alias:'justify-content',
                                    options:{
                                        label: this.$t('alignment'),
                                        css:{
                                            selector:'root .ecom-image-align'
                                        }
                                    }
                                }
                            }

                        ]
                    }
                } : null,

            ].filter(x => x);
            if(this.check('meta')) {
                style.push(
                {
                    group_alias: 'text:spacing',
                    options:{
                        selector: ' .ecom-shopify__blog--post-published-at',
                        group_name: 'blog_articles_datetime',
                        group_title: this.$t('datetime'),
                    }
                },
                {
                    group_alias: 'text:spacing',
                    options:{
                        selector: ' .ecom-shopify__blog--post-author',
                        group_name: 'blog_articles_author',
                        group_title: this.$t('author'),
                    }
                },
                {
                    group_alias: 'text:spacing',
                    options:{
                        selector: ' .ecom-shopify__blog--post-category a',
                        group_name: 'blog_articles_category',
                        group_title: this.$t('category'),
                    }
                },
                {
                    group_alias: 'text:spacing',
                    options:{
                        selector: ' .ecom-shopify__blog--post-comments_count',
                        group_name: 'blog_articles_comment_count',
                        group_title: this.$t('comment_count'),
                    }
                },
                {
                    group_alias:'icon',
                    options:{
                        group_name: 'icon',
                        group_title: this.$t('meta_icon'),
                        selector: ' .ecom-shopify__blog--post-informations-icon',
                    },
                    modify:{
                        params:[
                            {
                                position:15,
                                fields:[
                                    {
                                        type: 'line'
                                    },
                                    {
                                        alias:'spacing'
                                    }
                                ]
                            }
                        ]
                    }
                },
                {
                    group_alias:'image',
                    options:{
                        selector: ' .ecom-shopify__blog--post-informations-author-avatar',
                        liteMode: true,
                        group_name: 'blog_meta_img',
                        group_title: this.$t('meta_avatar'),
                    },
                    modify: {
                        remove: {
                            label: this.$t('width'),
                            length: 1
                        },
                        params: {
                            position: 1,
                            fields: [
                            {
                                type: "number",
                                name: "imageWidth",
                                label: this.$t('image_width'),
                                options: {
                                    responsive: true,
                                    reset: true,
                                    units: {
                                        "%": {
                                            min: 0,
                                            max: 100
                                        },
                                        px: {
                                            min: 0,
                                            max: 1000
                                        },
                                        vw: {
                                            min: 0,
                                            max: 100
                                        }
                                    }
                                },
                                css: {
                                    important: true,
                                    properties: {
                                        width: ""
                                    }
                                }
                            },
                            ]
                        }
                    }
                }
                )
            }

            if(this.check('link')) {
                style.push(
                {
                    group_alias: 'button',
                    options:{
                        selector: ' .ecom-shopify__blog--post-link-btn',
                        group_name: 'blog_articles_link_btn',
                        group_title: this.$t('read_more_link'),
                    },
                    modify: {
                        params: [
                            {
                                position: 0,
                                fields: [
                                    {
                                        type: 'paragraph',
                                        content: '** '+this.$t('icon')+' **',
                                        name: 'title_icon',
                                    },
                                    {
                                        name: "iconFontSize",
                                        label: this.$t('size'),
                                        type: "number",
                                        options: {
                                            responsive: true,
                                            units: {
                                                px: {
                                                    min: 0,
                                                    max: 300
                                                }
                                            }
                                        },
                                        css: {
                                            selector: " svg",
                                            properties: {
                                                height: "",
                                                width: ""
                                            }
                                        }
                                    },
                                    {
                                        name: "iconTransform",
                                        label: this.$t('rotate'),
                                        type: "number",
                                        options: {
                                            responsive: true,
                                            min: 0,
                                            max: 360
                                        },
                                        css: {
                                            selector: " svg",
                                            properties: {
                                                transform: "rotate(%value%deg)"
                                            }
                                        }
                                    },
                                    {
                                        type: 'choose',
                                        label: this.$t('icon_position'),
                                        name: 'icon_position',
                                        options: {
                                            type: 'align-x',
                                            values: [-1, 1],
                                        },
                                        css:{
                                            selector:' .ecom__element--button-icon',
                                            properties:{
                                                order:''
                                            }
                                        }
                                    },
                                    {
                                        type: 'number',
                                        label: this.$t('icon_spacing'),
                                        name: 'icon_spacing',
                                        options: {
                                            units: {
                                                px: {
                                                    min: 0,
                                                    max: 200
                                                }
                                            },
                                        },
                                        css:{
                                            properties:{
                                                gap:''
                                            }
                                        }
                                    },
                                    {
                                        type:'line'
                                    },
                                    {
                                        type: 'paragraph',
                                        content: "** "+this.$t('link')+" **",
                                        name: 'title_link',
                                    },
                                    {
                                        alias:'align-items',
                                        options:{
                                            label: this.$t('content_alignment'),
                                            name: 'content_alignment',
                                            css:{
                                                properties:{
                                                    'justify-content':''
                                                }
                                            }
                                        }
                                    }
                                ]
                            }
                        ]
                    }
                },
                )
            }

            if (this.data.template !== 'featured' && this.data.template !== 'related' && this.data.settings.enable_pagination && this.data.settings.layout !== 'slider') {
                style.push({
                    group_alias: 'pagination',
                    options:{
                        group_title: this.$t('pagination'),
                        selector: ' .ecom-pagination-navigation',
                        group_name: 'blog_articles_pagination',
                    },
                    modify: this.data.settings.pagination_style !== 'block' ? {
                        params: [
                            {
                                position:1,
                                fields: {
                                    type: 'choose',
                                    name: 'buttonAlignment',
                                    label: this.$t('alignment'),
                                    options: {
                                        responsive: true,
                                        type: 'text-align',
                                        values: ['flex-start', 'center', 'flex-end']
                                    },
                                    css: {
                                        properties: {
                                            display: 'flex',
                                            'justify-content': ''
                                        }
                                    }
                                }
                            },
                            {
                                position: 4,
                                fields: {
                                    type: 'choose',
                                    name: 'page_txt_alignment_horizontal',
                                    label: this.$t('text_alignment_small_horizontal_small'),
                                    options: {
                                        responsive: true,
                                        type: 'align-x-full',
                                        values: ['left', 'center', 'right']
                                    },
                                    css: {
                                        selector: ' .ecom-pagination-item',
                                        properties: {
                                            'text-align': '',
                                            'justify-content': ''
                                        }
                                    }
                                }
                            },
                            {
                                position: 4,
                                fields: {
                                    type: 'choose',
                                    name: 'page_txt_alignment_vertical',
                                    label: this.$t('text_alignment_small_vertical_small'),
                                    options: {
                                        responsive: true,
                                        type: 'align-y-full',
                                        values: ['start', 'center', 'end']
                                    },
                                    css: {
                                        selector: ' .ecom-pagination-item',
                                        properties: {
                                            'align-items': ''
                                        }
                                    }
                                }
                            },
                        ]
                    }: null
                });
            }
            let checkNavPagination = [];
            if(this.isArrow()){
                checkNavPagination.push({
                    title:this.$t('navigator'),
                    type:'swiper:nav'
                });
            }
            if(this.isPagination() && this.data.settings.slider_pagination_style != 'progress'){
                checkNavPagination.push({
                    title: this.$t('pagination'),
                    type:'swiper:pagination'
                });
            }
            let modifyNavigation = {};
            if(this.isCombined === 'combine') {
                modifyNavigation = {
                    params: [
                        {
                            alias: 'spacing',
                            options: {
                                name: 'spacingNavigation',
                                css: {
                                    selector: ' .ecom-swiper-navigation'
                                }
                            }
                        },
                        {
                            type: 'line'
                        }
                    ],
                    remove: {
                        name: 'justify-content'
                    }
                };
            }
            // Nút pause autoplay tồn tại độc lập với arrow/pagination nên phải push
            // group riêng, không gộp vào checkNavPagination (modifyNavigation splice
            // theo index, thêm field vào đó sẽ làm lệch vị trí các field khác).
            if (this.$helpers.hasAutoplayToggle(this.data?.settings)) {
                style.push({
                    group_alias: 'swiper:autoplay',
                    options: {
                        group_title: this.$t('pause_button'),
                        selector: ' .ecom-shopify__blog-wrapper'
                    }
                });
            }
            if (checkNavPagination.length) {
                if(this.data.settings.slider_pagination_style === 'progress' && this.isPagination()) {
                    modifyNavigation.params = [
                      {
                        position: 50,
                        fields: [
                          {
                            type: 'line'
                          },
                          {
                            type: 'paragraph',
                            content: this.$t('b_pagination')
                          },
                          {
                            type: 'number',
                            name: 'widthProgress',
                            label: this.$t('width'),
                            options: {
                            units: {
                                '%': {
                                min: 1,
                                max: 100
                                }
                            }
                            },
                            css: {
                                selector: ' .ecom-swiper-pagination.ecom-swiper-pagination-progressbar.ecom-swiper-pagination-horizontal',
                                important: true,
                                properties: {
                                    'width': ''
                                }
                            }
                        },
                          {
                            type: 'number',
                            name: 'sizeProgress',
                            label: this.$t('height'),
                            options: {
                              units: {
                                'px': {
                                  min: 1,
                                  max: 50
                                }
                              }
                            },
                            css: {
                              selector: ' .ecom-swiper-pagination-progressbar',
                              properties: {
                                '--ecom-swiper-pagination-progressbar-size': ''
                              }
                            }
                          },
                          {
                            type: "color",
                            name: "progress",
                            label: this.$t('progress'),
                            options: {
                                global: {
                                    type: "colors"
                                },
                                oneline: true,
                            },
                            css: {
                              selector: ' .ecom-swiper-pagination-progressbar-fill',
                              properties: {
                                'background-color': ''
                              }
                            }
                          },
                          {
                            type: "color",
                            name: "track",
                            label: this.$t('track'),
                            options: {
                                global: {
                                    type: "colors"
                                },
                                oneline: true,
                            },
                            css: {
                              selector: ' .ecom-swiper-pagination-progressbar',
                              properties: {
                                'background-color': ''
                              }
                            }
                          },
                          {
                            alias: 'spacing',
                            options: {
                              name: 'spacingPaginationProgress',
                              css: {
                                selector: ' .ecom-swiper-pagination-position.ecom-swiper-pagination-progressbar'
                              }
                            }
                          }
                        ]
                      }
                    ];
                }
                style.push({
                    group_alias: checkNavPagination,
                    options:{
                        group_title: this.$t('navigation'),
                        group_name: 'slider_arrow',
                        selector: ' .ecom-shopify__blog-wrapper',
                    },
                    modify: modifyNavigation
                });
            }



            style.push({
                group_alias: 'text:spacing',
                options: {
                    selector: ' .ecom-shopify__blog--empty-text',
                    group_name: 'blog_articles_empty_text',
                    group_title: this.$t('empty_articles_text'),
                }
            });

            return style;
        }
    }
};
</script>
